/// <summary>
/// Abstract class for document handling. All reguests from the mobile unit will be rerouted to a Document Handler class.
/// </summary>
abstract public class TFMDocumentHandler extends TFMInputHandler implements TFMTranslationDeclarantInterface
{
    TFMDocumentXML          resultStr;
    TFMXMLFormat            TFMXMLFormat;
    int                     sorting;    
    Common					resultTable;    
    DictMethod				MethodUsed;

}

