/// <summary>
/// Needs the TTS handling is requried. E.g. does this method post and change tables that requires the ttsbegin to be called outside the method.
/// </summary>
/// <returns></returns>
public boolean getTTSHandlingRequired()
{
    if(strScan( strLwr(request.parmName()), 'post', 0, 1000000) || 
       strScan( strLwr(request.parmDocumentType()), 'post', 0, 1000000) || 
       strScan( strLwr(request.parmDocumentType()), 'lockorder', 0, 1000000)
        )
    {
        return true;
    }
    return false;
}

    public ResourceName getIcon()
{
        ResourceName icon = resourceStr(TFMTaskletLogo);
        TFMMenuAttribute    menuAttribute;
        SysDictClass        DC;
        Array               attributeArray;
        int                 i;
        container		menuCon = this.registerMenu();
		if (menuCon != conNull())
        {
            icon = conPeek(conPeek(menuCon,1),4);
        }
        else
        {
            DC = new SysDictClass(classIdGet(this));

            attributeArray = DC.getAttributes(classStr(TFMMenuAttribute));
            for (i = 1; attributeArray && i <= attributeArray.lastIndex(); i++)
            {
                menuAttribute = attributeArray.value(i);
                icon = menuAttribute.parmIconName();
            }
        }
        return icon;
    }

public TFMDocumentHandler documenthandler()
{
    return this;
}

    public Common getResultTable()
    {

        TFMOrderPostDataSetAttribute		postOrderDataSet = new TFMOrderPostDataSetAttribute('');
        Map						datamethods = TFMAttributeHandler::getMethodNamesFromSysAttribute(classIdGet(this),postOrderDataSet,true);
        MapEnumerator						mEnum = datamethods.getEnumerator();
        while (mEnum.moveNext() && !resultTable)
        {
			if (SysTest::hasMethod(this,mEnum.currentKey()))
            {
                resultTable = new SysDictClass(classIdGet(this)).callObject(mEnum.currentKey(),this);
                if (resultTable.RecId)
                {
                    return resultTable;
                }
            }
        }
        return resultTable;
    }

