/// <summary>
/// The resulting XML from when the document has been processed.
/// </summary>
/// <returns>The resulting XML from when the document has been processed.</returns>
public XML getResult()
{
    if (resultXml)
    {
        return resultXml.outerXml();
    }

    return '';
}

/// <summary>
