{
    return resultStr;
}

    /// <summary>
    /// The resulting response Element
    /// </summary>
    /// <returns>A TFMResponseElement object containing the response.</returns>
    public TFMResponseElement getResponseElement()
    {
		if ( responseElement == null)
        {
            responseElement = new TFMResponseElement();
            responseElement.parmInnerXML(this.getResult());
            responseElement.parmResponseText(this.getResultStr());
        }
        responseElement.parmDeviceId(request.parmdeviceID());
        return responseElement;
    }

public void new()
{
    this.fillInParms();
}

public void fillInParms()
{
    //Fill all parm methods
    ClassId thisClassId = classIdGet(this);
    SetEnumerator methods = TFMFormLookupHelper::parmMethodsOnClass(thisClassId).getEnumerator();
    SysDictClass thisSysDictClass = new SysDictClass(thisClassId);

    while (methods.moveNext())
    {
        thisSysDictClass.callObject(methods.current(),this,TFMDocumentParameters::getValue(thisSysDictClass.name(),methods.current()));
    }
}

public static MethodName FindCorrespondingCollectorMethod(classID _classOverrideID, MethodName _methodName)
{
    DictClass                       DC = new DictClass(_classOverrideID);
    TFMCollectorMapAttribute        attr;
    Array                           array;
    int                             i, j;
    DictMethod                      DM;
    MethodName                      methodName = subStr(_methodName,1+strscan(_methodName,'.',1,strLen(_methodName)),strLen(_methodName));

    for (i = 1; i <= DC.objectMethodCnt(); i++)
    {
        DM = DC.objectMethodObject(i);
        array = DM.getAttributes(classStr(TFMCollectorMapAttribute));
        if (array != null)
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                attr = array.value(j);
                if (attr.parmDocumentType() == methodName)
                {
                    return DM.name();
                }
            }
        }
    }

    if (SysTest::hasMethod(DC.makeObject(),_methodName))
    {
        return _methodName;
    }

    return '';
}

public static MethodName FindCorrespondingPostMethod(classID _classOverrideID, MethodName _CollectorMethodName)
{
    SysDictClass                    DC = new SysDictClass(_classOverrideID);
    TFMCollectorMapAttribute        attr;
    TFMDocumentTypeAttribute        docTypeAttr;
    TFMDocumentContentSubject       content;
    TFMDocumentTypeId               docType;
    Array                           array;
    Array                           PMarray;
    int                             i, j;
    DictMethod                      DM, DMCollect;
    MethodName                      methodName = subStr(_CollectorMethodName,1+strscan(_CollectorMethodName,'.',1,strLen(_CollectorMethodName)),strLen(_CollectorMethodName));
    //SysTest::hasMethod

    for (i = 1; i <= DC.objectMethodCnt(); i++)
    {
        DMCollect =  DC.objectMethodObject(i);
        if (DMCollect.name() == methodName)
        {
            array = DMCollect.getAttributes(classStr(TFMCollectorMapAttribute));
            if (array != null)
            {
                for (j = 1; j <= array.lastIndex(); j++)
                {
                    attr = array.value(j);       
                    content = attr.parmContentType();
                    docType = attr.parmDocumentType();
                    break;
                }
            }                
        }
    }

    for (i = 1; i <= DC.objectMethodCnt(); i++)
    {
        DM = DC.objectMethodObject(i);
        array = DM.getAttributes(classStr(TFMDocumentTypeAttribute));
        PMarray = DM.getAttributes(classStr(TFMPostMethodAttribute));
        if (array != null && PMarray != null)
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                docTypeAttr = array.value(j);
                if (docTypeAttr.parmDocumentType() == substr(classStr(TFMPostAdhocRegistration),4,100) && docTypeAttr.parmContentType() == content)
                {
                    return DM.name();
                }
                else if (docTypeAttr.parmDocumentType() == docType && docTypeAttr.parmContentType() == content)
                {
                    return DM.name();
                }

            }
        }
    }

    return '';
}

/// <summary>
/// Generic method to find if there are additional steps setup to be added to the flow.
/// </summary>
/// <param name = "_methodName">The method name for which to check if additional steps has been set up.</param>
public void addFunctionCollectors(MethodName _methodName)
{
    DictClass                                       dc = new DictClass(classIdGet(this));
    ExecutePermission                               perm = new ExecutePermission();
    XmlElement                                      registrationCollectorConfigurationElement;
    XmlElement                                      stepsElement;
    str						                        name;
    Map                                             collectorMap;
    MapEnumerator                                   collectors;
    MethodName                                      requestName = TFMDocumentHandler::FindCorrespondingCollectorMethod(dc.id(),_methodName);
    SysDictMethod                                   sdm;
    Array                                           attrArr;
    int                                             arrIndex;
    TFMCollectorConfigurationAdditionalAttribute    additionalAttr;

    resultXml       = new XmlDocument();

    if (sysTest::hasMethod(this,requestName))
    {
        Perm.assert();
        collectorMap = dc.callObject(requestName,this);
        CodeAccessPermission::revertAssert();
    }
    else
    {
        throw Error(strFmt("@TFM:RequestTypeDoesNotExist",requestName));
    }
    // Create the registrationCollectorConfiguration element
    registrationCollectorConfigurationElement = resultXml.createElement(TFMConstants::registrationCollectorConfiguration());

    //registrationCollectorConfigurationElement.setAttribute('noStepsBehaviour','Post');

    // Create the steps element
    stepsElement = resultXml.createElement(TFMConstants::steps());
    registrationCollectorConfigurationElement.appendChild(stepsElement);

    sdm = new SysDictMethod(UtilElementType::ClassInstanceMethod, classIdGet(this), requestName);
    attrArr = sdm.getAttributes(classStr(TFMCollectorConfigurationAdditionalAttribute));
    for (arrIndex = 1; arrIndex <= attrArr.lastIndex(); arrIndex++)
    {
        additionalAttr = attrArr.value(arrIndex);
        registrationCollectorConfigurationElement.setAttribute(additionalAttr.parmAttributeName(), additionalAttr.parmValue());
    }
    this.addToCollectors(collectorMap,classIdget(this),requestName);
    collectors = collectorMap.getEnumerator();
    while (collectors.moveNext())
    {
        name = TFMConstants::add();
        if ('typeAndQuantity' == collectors.currentValue().lookup('inputType'))
        {
            name = 'typeAndQuantity';
        }
        TFMRegistrationCollector::addGenericRegistrationStep(stepsElement,name,collectors.currentValue());
    }

    resultXml.appendChild(registrationCollectorConfigurationElement);
}

public void addToCollectors(Map _collectors, ClassId _orderClass, MethodName _methodName)
{
    // By default we do not have any collectors to add, but if the document handler wants to add collectors based on user setup, it can override this method and add collectors to the flow.
}

public Map getCollectorMap(TFMDocumentTypeId _documentType, TFMDocumentContentSubject _contentType = '', Map _additionalValues = new Map(Types::String, Types::String))
{
    Map                         collectorMap;
    DictClass                   dc = new DictClass(classIdGet(this));
    TFMCollectorMapAttribute    attribute = new TFMCollectorMapAttribute(_documentType, _contentType);
    ExecutePermission           perm = new ExecutePermission();
    DictMethod                  Method = TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(this),attribute);
    TFMDocumentTypeAttribute    docTypeAttr;
    if (Method == null)
    {
        docTypeAttr = new TFMDocumentTypeAttribute(classStr(TFMGetRegistrationConfiguration), _contentType);
        Method = TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(this),docTypeAttr);
    }

    if (Method && sysTest::hasMethod(this,Method.name()))
    {
        Perm.assert();
        collectorMap = dc.callObject(Method.name(),this);
        CodeAccessPermission::revertAssert();
    }

    return collectorMap;
}

public Map getRequestDataMap()
{
    Map reqDataMap = new Map(Types::String, Types::String);
    XmlElement reqData = requestXml != null ? requestXml.root().getNamedElement(TFMConstants::requestData()) : null;

    if ( reqData == null)
    {
        return reqDataMap;
    }

    reqData = reqData.firstChild();

    if ( reqData == null)
    {
        return reqDataMap;
    }
    while(reqData)
    {
        reqDataMap.insert(reqData.name(),reqData.innerXml());
        reqData = reqData.nextSibling();
    }
    return reqDataMap;
}

protected ClassId getAncestor(Object _class)
{
    ClassId finalClassId = new SysDictClass(classIdGet(_class)).extend();

    while (new SysDictClass(finalClassId).extend())
    {
        finalClassId = new SysDictClass(finalClassId).extend();
    }
    return finalClassId;
}

    /// <summary>
    /// Method to process the received document. This method must be overridden in sub-classes.
    /// </summary>
    public void process()
    {
        str                         requestName;
        DictClass                   dc = new DictClass(classIdGet(this));
        ExecutePermission           perm = new ExecutePermission();
        anytype						retVal;
        TFMResponseElement			responseData;

        resultXml       = new XmlDocument();
        requestName     = request.parmName();

        if (sysTest::hasMethod(this,requestName))
        {
            Perm.assert();
            retVal = dc.callObject(requestName,this);

            if (typeOf(retVal) == Types::String)
            {
                resultStr = retVal;
            }
            else if (typeOf(retVal) == Types::Class && this.getAncestor(retVal) == classNum(TFMResponseElement))
            {
                responseData = retVal;
                resultStr = responseData.parmResponseText();
                responseElement = responseData;
            }
            CodeAccessPermission::revertAssert();
        }
		//else if (dc.get) //Check for method with attribute
        else
        {
            throw Error(strFmt("@TFM:RequestTypeDoesNotExist",requestName));
        }        
    }

/// <summary>
/// Method used to determine whether or not a given method is a Posting method.
/// </summary>
/// <param name = "_requestName">The name of the method to be checked.</param>
/// <returns>True, if method is a post method (i.e. has the TFMPostMethod attribute). Otherwise false.</returns>
public boolean isPostMethod(str _requestName)
{

    DictClass                       DC = new DictClass(classIdGet(this));
    Object                          attr;
    Array                           array;
    int                             i, j;
    DictMethod                      DM;

    for (i = 1; i <= DC.objectMethodCnt(); i++)
    {
        DM = DC.objectMethodObject(i);
        if (DM.name() != _requestName)
        {
            continue;
        }
        array = DM.getAttributes(classStr(TFMPostMethodAttribute));
        if (array != null)
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                attr = array.value(j);
                return true;
            }
        }
    }
    return false;
}

/// <summary>
/// The run method, always executed.
/// </summary>
final public void run()
{
    infolog.language(new xInfo().language());
    this.fillInParms();
    this.process();
}

public Set getAllDocumentTypes(ClassName _clsName = classStr(TFMDocumenttypeAttribute))
{
    Set methodDocs = this.getDocumentTypes();
    SysDictClass sdc = new SysDictClass(classIdGet(this));
    Array arr = sdc.getAttributes(_clsName);
    int j;
    Object attrObject;
    if (arr != null)
    {
        for (j = 1; j <= arr.lastIndex(); j++)
        {

            attrObject = arr.value(j);
            if (SysTest::hasMethod(attrObject, methodStr(TFMDocumenttypeAttribute,parmDocumentType)) && !methodDocs.in(attrObject.parmDocumentType()) && !attrObject.parmContentType())
            {
                methodDocs.add(attrObject.parmDocumentType());
            }
            else if (SysTest::hasMethod(attrObject, methodStr(TFMOrderListGetOrdersDocumentTypeAttribute,parmMethodName)))
            {
                methodDocs.add(attrObject.parmMethodName());
            }
        }
    }

    return methodDocs;
}

