public static TFMDocumentHandler newClassId(ClassId _classId)
{
    DictClass           dictClass;
    Object              action;

    if (! _classId)
    {
        return null;
    }
    if (! SysDictClass::isSuperclass(_classId,classnum(TFMDocumentHandler )))
    {
        return null;
    }
    dictClass       = new DictClass(_classId);
    action          = dictClass.makeObject();

    return action;
}
